"""Distinct native SVG upgrade symbols; ivory/gold/violet project UI palette."""

def icons():
    seed='<path d="M60 24C42 36 30 59 33 78C36 103 75 111 90 87C105 63 78 37 60 24Z" fill="url(#toxic)"/><path d="M62 37C52 53 49 72 60 89" fill="none" stroke="#efddff" stroke-width="5"/>'
    petals=lambda count,wide:''.join(f'<path d="M64 63Q{64-wide} 35 64 13Q{64+wide} 35 64 63Z" transform="rotate({i*360/count} 64 64)" fill="url(#ivory)"/>' for i in range(count))
    return {
      'NB_Toxic1':seed+'<circle cx="24" cy="41" r="9" fill="#a3e8f3"/><circle cx="98" cy="29" r="12" fill="url(#toxic)"/><circle cx="107" cy="67" r="7" fill="#e9adf7"/>',
      'NB_Toxic2':'<path d="M15 87C10 62 29 46 45 45C45 21 73 14 88 32C109 26 121 49 109 65C126 92 95 109 78 94C54 114 36 93 15 87Z" fill="url(#toxic)"/><path d="M27 77Q54 81 67 55T103 49" fill="none" stroke="#b6efff" stroke-width="6"/><circle cx="31" cy="37" r="7" fill="#efc3fa"/><circle cx="60" cy="90" r="9" fill="#faeaff"/><circle cx="90" cy="79" r="6" fill="#a3e8f3"/>',
      'NB_Toxic3':petals(5,21)+'<path d="M64 35L72 52L93 56L78 71L81 94L63 82L44 94L48 72L32 57L55 52Z" fill="url(#toxic)"/><circle cx="64" cy="65" r="14" fill="url(#core)"/><path d="M11 45L22 50M105 38L116 31M14 95L24 88M103 99L115 105" stroke="#dda1ff" stroke-width="6"/>',
      'NB_Toxic4':'<path d="M12 66C3 48 18 31 34 35C35 12 66 11 75 30C97 15 124 42 111 60L99 69H27Z" fill="url(#toxic)"/><path d="M26 53Q60 34 103 51" fill="none" stroke="#c4e8ff" stroke-width="5"/><path d="M29 75L23 93M57 75L57 109M86 75L92 101" stroke="#b58be9" stroke-width="9"/><circle cx="21" cy="108" r="6" fill="#d7a5ff"/><circle cx="111" cy="83" r="7" fill="#afebf4"/>',
      'NB_Toxic5':'<path d="M18 89L15 46L36 59L45 15L65 42L86 14L96 57L115 42L109 88Q65 111 18 89Z" fill="url(#ivory)"/><path d="M35 87Q22 50 48 46Q55 67 64 76Q76 51 92 43Q111 72 88 91Z" fill="url(#toxic)"/><path d="M64 93C42 81 42 60 64 48C86 59 90 80 64 93Z" fill="url(#core)"/><circle cx="64" cy="108" r="7" fill="#f1b4f4"/><circle cx="15" cy="24" r="6" fill="#9be6ff"/><circle cx="112" cy="17" r="6" fill="#e99ee9"/>',
      'NB_Burst1':'<path d="M64 12C86 29 103 51 99 80L84 103L64 116L43 103L29 80C25 51 42 28 64 12Z" fill="url(#ivory)"/><path d="M64 30L44 60L48 87L64 100L80 87L84 60Z" fill="url(#core)"/><path d="M30 71Q64 89 98 71M40 42L49 56M87 42L78 56" fill="none" stroke="#cda45c" stroke-width="7"/>',
      'NB_Burst2':'<circle cx="64" cy="64" r="34" fill="url(#core)"/><ellipse cx="64" cy="64" rx="48" ry="17" transform="rotate(-28 64 64)" fill="none" stroke="#ead29a" stroke-width="7"/><path d="M56 18L64 6L72 18M109 55L122 63L109 72M55 110L64 123L73 110M18 55L6 63L18 72" fill="none" stroke="#b1eafa" stroke-width="6"/>',
      'NB_Burst3':'<path d="M64 6L75 34L100 19L94 47L122 55L98 72L112 99L83 92L69 122L55 96L24 111L33 81L7 67L34 55L19 25L49 35Z" fill="url(#ivory)"/><path d="M64 29L73 52L98 59L78 75L70 101L55 80L31 68L53 54Z" fill="url(#core)"/><circle cx="65" cy="65" r="12" fill="#effcff" stroke="#a8ddff"/>',
      'NB_Burst4':'<path d="M65 5L79 43L115 24L92 60L123 74L87 83L106 113L73 94L59 124L48 89L15 107L34 74L5 58L42 47L24 15L56 37Z" fill="url(#ivory)"/><path d="M65 25L76 52L102 67L77 78L61 106L51 79L27 62L51 51Z" fill="url(#core)"/><ellipse cx="65" cy="65" rx="51" ry="18" transform="rotate(-38 65 65)" fill="none" stroke="#a2e8f8" stroke-width="6"/><circle cx="65" cy="65" r="11" fill="#f7fdff"/>',
      'NB_Burst5':'<path d="M14 43A54 54 0 0 1 48 10M82 10A54 54 0 0 1 117 45M116 87A54 54 0 0 1 83 118M45 117A54 54 0 0 1 10 82" fill="none" stroke="#b4dbff" stroke-width="6"/>'+petals(8,15)+'<path d="M64 25L76 47L103 42L87 65L105 88L77 83L64 108L52 84L26 90L42 66L25 43L52 48Z" fill="url(#core)"/><path d="M64 40L71 57L88 64L71 71L64 89L57 71L40 64L57 57Z" fill="#f7ffff" stroke="#bcdbff"/>',
    }

def write_icons(folder):
    defs='<defs><linearGradient id="ivory" x2="100%" y2="100%"><stop stop-color="#fff4d7"/><stop offset=".48" stop-color="#e4d9ed"/><stop offset="1" stop-color="#a28ec5"/></linearGradient><linearGradient id="toxic" x2="80%" y2="100%"><stop stop-color="#eda4f1"/><stop offset=".5" stop-color="#9564d6"/><stop offset="1" stop-color="#49327c"/></linearGradient><radialGradient id="core"><stop stop-color="#f0fdff"/><stop offset=".28" stop-color="#9adeff"/><stop offset=".6" stop-color="#9675ee"/><stop offset="1" stop-color="#43267f"/></radialGradient></defs>'
    for name,body in icons().items():
        (folder/(name+'.svg')).write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128">{defs}<g stroke="#dec28b" stroke-width="3.5" stroke-linejoin="round" stroke-linecap="round">{body}</g></svg>',encoding='utf-8')
